/*
 * Documentation-grade semantic C for the completed-Level-B replacement
 * transition re-localization. This is not matching source and is not a build
 * input. Exact opcodes, predecessor edges, retained-anchor identities and
 * source hashes are regenerated by
 * tools/phase4_fmv_levelb_transition_relocalization.py.
 */

extern void scene_setup_and_load(int scene, int transition);

/*
 * The natural completed-Level-B owner returns to the resident scene-flow
 * dispatcher. Its pending request has two classified replacement choices:
 *
 *   negative pending request    -> 0x8004FD74: scene_setup_and_load(3, 0)
 *   nonnegative pending request -> 0x8005029C: scene_setup_and_load(6, 128)
 *
 * Both transitions differ from the -1 resource-skip sentinel. The matching
 * scene_setup_and_load source therefore calls resource_id_dat_load_dispatcher
 * with selector zero, which materializes bits\memory.bin and Region-B
 * destination 0x800B5788 before the later CdRead at 0x80046078.
 *
 * A retained pristine atomic anchor at frame 15816 is already paused in the
 * scene-flow wait block at 0x8004FEA4 and its Region-B head differs from the
 * FMV.BIN head. The failed 15816..15880 exact-PC runs are therefore preserved
 * as evidence that frame 15816 is not a valid pre-submit anchor. A future
 * first-hit stop must begin earlier and cover both branch-specific callsites.
 * Static code does not choose the natural branch at a frame boundary and does
 * not establish a DMA event, cycle, direction, sector sequence, or success.
 */
static void completed_level_b_replacement_transition(int pending_request)
{
    if (pending_request < 0)
        scene_setup_and_load(3, 0);
    else
        scene_setup_and_load(6, 128);
}
